// Stands in for the Claude Agent SDK under tests/test_chat_bridges.py: query() records how it was
// called in $FAKE_LOG (one JSON line each) and answers every prompt with the messages in
// $FAKE_SCRIPT, as the real one streams Claude Code's. An entry {"ask": input} consults the
// bridge's canUseTool for AskUserQuestion and reports what it decided as the tool's result.
import { appendFileSync, readFileSync } from 'node:fs';

const log = entry => appendFileSync(process.env.FAKE_LOG, JSON.stringify(entry) + '\n');

export async function getSessionMessages(id, options) {
  log({ history: id, dir: options.dir });
  return JSON.parse(process.env.FAKE_HISTORY || '[]');
}

export function query({ prompt, options }) {
  const states = !!options.env?.CLAUDE_CODE_EMIT_SESSION_STATE_EVENTS && !process.env.FAKE_STATELESS;  // sent only when asked for
  log({ options: { ...options, env: Object.keys(options.env || {}).filter(k => !(k in process.env)), canUseTool: typeof options.canUseTool, stderr: typeof options.stderr } });
  const script = JSON.parse(readFileSync(process.env.FAKE_SCRIPT, 'utf8'));
  async function* run() {
    yield { type: 'system', subtype: 'init', model: 'claude-test-1' };
    for await (const message of prompt) {
      log({ prompt: message.message.content });
      if (states) yield { type: 'system', subtype: 'session_state_changed', state: 'running' };
      for (const out of script) {
        if (!out.ask) { yield out; continue; }
        const decided = await options.canUseTool('AskUserQuestion', out.ask, { signal: new AbortController().signal });
        yield { type: 'user', parent_tool_use_id: null,
                message: { content: [{ type: 'tool_result', tool_use_id: 'ask', content: JSON.stringify(decided) }] } };
      }
      if (states) yield { type: 'system', subtype: 'session_state_changed', state: 'idle' };
    }
  }
  return Object.assign(run(), {
    initializationResult: async () => ({
      claude_code_version: '1.2.3', account: { email: 'someone@example.com' },
      models: [{ value: 'default', displayName: 'Default', description: 'Test 1 · Everyday' }],
      commands: [{ name: 'compact', description: 'Summarise', argumentHint: '[instructions]' }] }),
    interrupt: async () => log({ interrupt: true }),
    setModel: async id => log({ model: id }),
    applyFlagSettings: async settings => log({ settings }),
    getContextUsage: async () => ({ totalTokens: 1200, maxTokens: 200000 }),
  });
}
